func TestRenderGithubSetupWorkflow(t *testing.T) {
	workflow := renderGithubSetupWorkflow("api", "acme/api", "release/canary", githubSetupRolloutStandard, nil, "", false)
	for _, want := range []string{
		"generated by `gregale github setup`",
		"branches:\n      - \"release/canary\"",
		"if: ${{ github.event_name != 'workflow_dispatch' || github.ref == 'refs/heads/release/canary' }}",
		"name: ${{ 'production' }}",
		"environment: ${{ '' }}",
		"tags:\n      - \"v*\"",
		"poyrazK/faas/.github/actions/deploy@" + githubActionDefaultSHA + " # v0",
		"# Action: poyrazK/faas/.github/actions/deploy@" + githubActionDefaultSHA,
		`wait: "true"`,
		"concurrency:\n  group: gregale-${{ github.repository }}-api-${{ 'default' }}",
		"cancel-in-progress: false",
		"PR previews are managed by the connected GitHub integration.",
	} {
		if !strings.Contains(workflow, want) {
			t.Errorf("workflow does not contain %q:\n%s", want, workflow)
		}
	}
	if strings.Contains(workflow, "pull_request:") {
		t.Fatal("production workflow must not deploy on pull_request events")
	}
	if strings.Contains(workflow, `rollout: "safe"`) {
		t.Fatal("standard production workflow must not opt into safe rollout")
	}
}

