func TestEnsureGithubActionsDependabotPreservesAndMergesConfig(t *testing.T) {
	existing := []byte("# Keep the existing Go dependency policy.\nversion: 2\nupdates:\n  - package-ecosystem: gomod\n    directory: /\n    schedule:\n      interval: daily\n    labels:\n      - go\n")
	merged, changed, err := ensureGithubActionsDependabot(existing, true)
	if err != nil {
		t.Fatalf("merge Dependabot config: %v", err)
	}
	if !changed {
		t.Fatal("merge did not report its added GitHub Actions updater")
	}
	for _, want := range []string{
		"# Keep the existing Go dependency policy.",
		"package-ecosystem: gomod",
		"interval: daily",
		"labels:",
		"package-ecosystem: github-actions",
		"directory: /",
		"interval: weekly",
	} {
		if !strings.Contains(string(merged), want) {
			t.Errorf("merged Dependabot config omits %q:\n%s", want, merged)
		}
	}
	var parsed yaml.Node
	if err := yaml.Unmarshal(merged, &parsed); err != nil {
		t.Fatalf("merged config is invalid YAML: %v", err)
	}
}

func TestEnsureGithubActionsDependabotIsIdempotent(t *testing.T) {
	for _, directory := range []string{"/", "/packages/api"} {
		existing := []byte("version: 2\nupdates:\n  - package-ecosystem: github-actions\n    directory: " + directory + "\n    schedule:\n      interval: daily\n")
		merged, changed, err := ensureGithubActionsDependabot(existing, true)
		if err != nil {
			t.Fatalf("merge existing %s Actions entry: %v", directory, err)
		}
		if directory == "/" {
			if changed || !bytes.Equal(merged, existing) {
				t.Fatal("existing root Actions entry was changed")
			}
			continue
		}
		if !changed || !strings.Contains(string(merged), "interval: daily") || !strings.Contains(string(merged), "interval: weekly") {
			t.Fatalf("subdirectory entry was not preserved alongside the new root entry:\n%s", merged)
		}
	}
}

