func TestCmdGithubSetupRestoresWorkflowWhenPolicyUpdateFails(t *testing.T) {
	for _, existed := range []bool{false, true} {
		t.Run(strconv.FormatBool(existed), func(t *testing.T) {
			repoDir := t.TempDir()
			if err := os.Mkdir(filepath.Join(repoDir, ".git"), 0o755); err != nil {
				t.Fatal(err)
			}
			t.Chdir(repoDir)
			path := filepath.Join(repoDir, defaultGithubSetupWorkflow)
			dependabotPath := filepath.Join(repoDir, defaultGithubSetupDependabotPath)
			previous := []byte("name: existing\n")
			previousDependabot := []byte("version: 2\nupdates:\n  - package-ecosystem: gomod\n    directory: /\n    schedule:\n      interval: daily\n")
			if existed {
				if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
					t.Fatal(err)
				}
				if err := os.WriteFile(path, previous, 0o644); err != nil {
					t.Fatal(err)
				}
				if err := os.WriteFile(dependabotPath, previousDependabot, 0o644); err != nil {
					t.Fatal(err)
				}
			}
			srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				if r.Method == http.MethodGet && r.URL.Path == "/v1/apps/api/github" {
					_, _ = w.Write([]byte(`{"connected":true,"installation_id":42,"repo_full_name":"acme/api","production_branch":"main"}`))
					return
				}
				if r.Method == http.MethodPatch && r.URL.Path == "/v1/apps/api/github/deployment-policy" {
					http.Error(w, "policy update failed", http.StatusInternalServerError)
					return
				}
				http.NotFound(w, r)
			}))
			defer srv.Close()
			t.Setenv("FAAS_API", srv.URL)
			t.Setenv("FAAS_TOKEN", "fp_live_test")
			args := []string{"api", "--enable-action-updates"}
			if existed {
				args = append(args, "--force")
			}
			if code := cmdGithubSetup(args); code == 0 {
				t.Fatal("setup succeeded despite failed policy update")
			}
			data, err := os.ReadFile(path)
			if existed {
				if err != nil || !bytes.Equal(data, previous) {
					t.Fatalf("workflow after rollback = %q, %v", data, err)
				}
			} else if !os.IsNotExist(err) {
				t.Fatalf("new workflow remained after rollback: %q, %v", data, err)
			}
			dependabotAfter, err := os.ReadFile(dependabotPath)
			if existed {
				if err != nil || !bytes.Equal(dependabotAfter, previousDependabot) {
					t.Fatalf("Dependabot config after rollback = %q, %v", dependabotAfter, err)
				}
			} else if !os.IsNotExist(err) {
				t.Fatalf("new Dependabot config remained after rollback: %q, %v", dependabotAfter, err)
			}
		})
	}
}

func TestValidGithubSetupRollout(t *testing.T) {
	for _, tc := range []struct {
		value string
		want  bool
	}{
		{githubSetupRolloutStandard, true},
		{githubSetupRolloutSafe, true},
		{"", false},
		{"balanced", false},
	} {
		if got := validGithubSetupRollout(tc.value); got != tc.want {
			t.Errorf("validGithubSetupRollout(%q) = %t, want %t", tc.value, got, tc.want)
		}
	}
}

