func TestCmdGithubSetupBindsAndIsIdempotent(t *testing.T) {
	repoDir := t.TempDir()
	if err := os.Mkdir(filepath.Join(repoDir, ".git"), 0o755); err != nil {
		t.Fatal(err)
	}
	t.Chdir(repoDir)
	dependabotPath := filepath.Join(repoDir, defaultGithubSetupDependabotPath)
	if err := os.MkdirAll(filepath.Dir(dependabotPath), 0o755); err != nil {
		t.Fatal(err)
	}
	dependabotBefore := []byte("version: 2\nupdates:\n  - package-ecosystem: gomod\n    directory: /\n    schedule:\n      interval: daily\n")
	if err := os.WriteFile(dependabotPath, dependabotBefore, 0o644); err != nil {
		t.Fatal(err)
	}

	var bindRequest api.InstallBindRequest
	var bindCalls int
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		switch {
		case r.Method == http.MethodGet && r.URL.Path == "/v1/apps/api/github":
			_, _ = w.Write([]byte(`{"connected":true,"installation_id":42,"repo_full_name":"acme/api","production_branch":"main"}`))
		case r.Method == http.MethodPost && r.URL.Path == "/v1/apps/api/github/bind":
			bindCalls++
			if err := json.NewDecoder(r.Body).Decode(&bindRequest); err != nil {
				t.Errorf("decode bind request: %v", err)
			}
			_, _ = w.Write([]byte(`{"binding_id":"bind-1","repo_full_name":"acme/api","production_branch":"trunk"}`))
		case r.Method == http.MethodPatch && r.URL.Path == "/v1/apps/api/github/deployment-policy":
			var patch api.GitHubDeploymentPolicyPatch
			if err := json.NewDecoder(r.Body).Decode(&patch); err != nil || patch.ProductionTrigger == nil || *patch.ProductionTrigger != "actions" {
				t.Errorf("invalid setup policy patch: %+v, %v", patch, err)
			}
			_, _ = w.Write([]byte(`{"project_id":"project-1","production_trigger":"actions"}`))
		default:
			http.NotFound(w, r)
		}
	}))
	defer srv.Close()
	t.Setenv("FAAS_API", srv.URL)
	t.Setenv("FAAS_TOKEN", "fp_live_test")

	oldOut, oldJSON := osStdout, jsonOutput
	var out bytes.Buffer
	osStdout, jsonOutput = &out, false
	t.Cleanup(func() { osStdout, jsonOutput = oldOut, oldJSON })

	args := []string{"api", "--repo", "acme/api", "--production-branch", "trunk", "--deploy-branches", "main=production,staging=staging", "--enable-action-updates"}
	if code := cmdGithubSetup(args); code != 0 {
		t.Fatalf("first setup exit = %d, output = %s", code, out.String())
	}
	workflowPath := filepath.Join(repoDir, defaultGithubSetupWorkflow)
	workflow, err := os.ReadFile(workflowPath)
	if err != nil {
		t.Fatalf("read generated workflow: %v", err)
	}
	if !strings.Contains(string(workflow), `- "trunk"`) || !strings.Contains(string(workflow), `- "staging"`) || !strings.Contains(string(workflow), `&& 'staging' || '' }}`) || strings.Contains(string(workflow), "pull_request:") {
		t.Fatalf("unexpected workflow:\n%s", workflow)
	}
	if bindRequest.InstallationID != 42 || bindRequest.RepoFullName != "acme/api" || bindRequest.ProductionBranch != "trunk" || bindRequest.DeployBranches["main"] != "production" {
		t.Fatalf("bind request = %+v", bindRequest)
	}
	if bindCalls != 1 {
		t.Fatalf("bind calls after first setup = %d", bindCalls)
	}

	out.Reset()
	if code := cmdGithubSetup(args); code != 0 {
		t.Fatalf("idempotent setup exit = %d, output = %s", code, out.String())
	}
	if bindCalls != 2 {
		t.Fatalf("bind calls after second setup = %d", bindCalls)
	}
	workflowAgain, err := os.ReadFile(workflowPath)
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(workflow, workflowAgain) {
		t.Fatal("idempotent setup changed the workflow")
	}
	dependabotAfter, err := os.ReadFile(dependabotPath)
	if err != nil {
		t.Fatalf("read Dependabot config: %v", err)
	}
	if !strings.Contains(string(dependabotAfter), "package-ecosystem: gomod") || !strings.Contains(string(dependabotAfter), "interval: daily") || !strings.Contains(string(dependabotAfter), "package-ecosystem: github-actions") || !strings.Contains(string(dependabotAfter), "interval: weekly") {
		t.Fatalf("setup did not preserve existing Dependabot settings while adding Actions:\n%s", dependabotAfter)
	}
	if !strings.Contains(out.String(), "already matches") {
		t.Fatalf("expected idempotent receipt, got %s", out.String())
	}
}

func TestCmdGithubSetupUsesSavedDeployBranchMappings(t *testing.T) {
	repoDir := t.TempDir()
	if err := os.Mkdir(filepath.Join(repoDir, ".git"), 0o755); err != nil {
		t.Fatal(err)
	}
	t.Chdir(repoDir)
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		switch {
		case r.Method == http.MethodGet && r.URL.Path == "/v1/apps/api/github":
			_, _ = w.Write([]byte(`{"connected":true,"installation_id":42,"repo_full_name":"acme/api","production_branch":"main","deploy_branches":{"staging":"staging"}}`))
		case r.Method == http.MethodPatch && r.URL.Path == "/v1/apps/api/github/deployment-policy":
			_, _ = w.Write([]byte(`{"project_id":"project-1","production_trigger":"actions"}`))
		default:
			http.NotFound(w, r)
		}
	}))
	defer srv.Close()
	t.Setenv("FAAS_API", srv.URL)
	t.Setenv("FAAS_TOKEN", "fp_live_test")

	oldOut, oldJSON := osStdout, jsonOutput
	var out bytes.Buffer
	osStdout, jsonOutput = &out, false
	t.Cleanup(func() { osStdout, jsonOutput = oldOut, oldJSON })

	if code := cmdGithubSetup([]string{"api"}); code != 0 {
		t.Fatalf("setup exit = %d, output = %s", code, out.String())
	}
	workflow, err := os.ReadFile(filepath.Join(repoDir, defaultGithubSetupWorkflow))
	if err != nil {
		t.Fatalf("read generated workflow: %v", err)
	}
	for _, want := range []string{`- "staging"`, `&& 'staging' || '' }}`} {
		if !strings.Contains(string(workflow), want) {
			t.Errorf("setup omitted saved mapping %q:\n%s", want, workflow)
		}
	}
}

func TestCmdGithubSetupDryRunDoesNotWriteOrCallAPI(t *testing.T) {
	repoDir := t.TempDir()
	if err := os.Mkdir(filepath.Join(repoDir, ".git"), 0o755); err != nil {
		t.Fatal(err)
	}
	t.Chdir(repoDir)
	called := false
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		called = true
		http.Error(w, "unexpected network call", http.StatusInternalServerError)
	}))
	defer srv.Close()
	t.Setenv("FAAS_API", srv.URL)
	t.Setenv("FAAS_TOKEN", "fp_live_test")

	oldOut, oldJSON := osStdout, jsonOutput
	var out bytes.Buffer
	osStdout, jsonOutput = &out, false
	t.Cleanup(func() { osStdout, jsonOutput = oldOut, oldJSON })

	sha := "f1e2d3c4b5a6987654321098765432109abcdef0"
	if code := cmdGithubSetup([]string{"api", "--repo", "acme/api", "--production-branch", "main", "--rollout", "safe", "--pinned-sha", sha, "--enable-action-updates", "--dry-run"}); code != 0 {
		t.Fatalf("dry-run exit = %d, output = %s", code, out.String())
	}
	if called {
		t.Fatal("dry-run made an API request")
	}
	if _, err := os.Stat(filepath.Join(repoDir, defaultGithubSetupWorkflow)); !os.IsNotExist(err) {
		t.Fatalf("dry-run created workflow, stat err = %v", err)
	}
	if _, err := os.Stat(filepath.Join(repoDir, defaultGithubSetupDependabotPath)); !os.IsNotExist(err) {
		t.Fatalf("dry-run created Dependabot config, stat err = %v", err)
	}
	if !strings.Contains(out.String(), "Generated workflow:") {
		t.Fatalf("dry-run did not show generated workflow: %s", out.String())
	}
	if !strings.Contains(out.String(), `rollout: "safe"`) || !strings.Contains(out.String(), "rollout:            safe") {
		t.Fatalf("dry-run did not show safe rollout mode: %s", out.String())
	}
	if !strings.Contains(out.String(), "uses: poyrazK/faas/.github/actions/deploy@"+sha) {
		t.Fatalf("dry-run did not render pinned Action SHA: %s", out.String())
	}
	if !strings.Contains(out.String(), "Dependabot config .github/dependabot.yml:") || !strings.Contains(out.String(), "package-ecosystem: github-actions") || !strings.Contains(out.String(), "dependabot:        would be updated") {
		t.Fatalf("dry-run did not preview the Dependabot config: %s", out.String())
	}
}
